-- Owner-authorized UBL legacy PO/site links. No workflow transitions or emails.
CREATE TABLE ubl_site_orders (
 site_id integer PRIMARY KEY REFERENCES sites(id),
 source_row integer NOT NULL UNIQUE,
 branch_code text NOT NULL UNIQUE,
 site_name text NOT NULL, region text NOT NULL, main_city text NOT NULL,
 configuration_id text REFERENCES ubl_configurations(id), pricing_stage text,
 po_number text UNIQUE, po_issued_date date, legacy_ipo_number text NOT NULL UNIQUE,
 status text NOT NULL CHECK(status IN ('Active','Cancelled','Awaiting revised PO')),
 notes text NOT NULL, baseline jsonb, source jsonb NOT NULL,
 linked_at timestamptz NOT NULL DEFAULT now(),
 CHECK ((configuration_id IS NULL)=(baseline IS NULL)),
 CHECK ((pricing_stage IS NULL)=(baseline IS NULL)),
 CHECK ((status='Awaiting revised PO')=(baseline IS NULL)),
 FOREIGN KEY(configuration_id,pricing_stage) REFERENCES ubl_commercial_history(configuration_id,stage)
);
CREATE TRIGGER immutable_ubl_site_orders BEFORE UPDATE OR DELETE ON ubl_site_orders FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
LOCK TABLE sites IN EXCLUSIVE MODE;
DO $link$
