 FOR r IN SELECT value FROM jsonb_array_elements(data) LOOP
  SELECT count(*),min(id) INTO matches,linked_site FROM sites WHERE customer_id=customer AND lower(trim(code))=lower(r->>'branchCode');
  IF matches>1 THEN RAISE EXCEPTION 'Multiple UBL sites match branch code %',r->>'branchCode'; END IF;
  IF matches=0 THEN
   SELECT COALESCE(max(id),0)+1 INTO linked_site FROM sites;
   INSERT INTO sites(id,customer_id,name,code,location,status) VALUES(linked_site,customer,r->>'name',r->>'branchCode',concat_ws(' · ',nullif(r->>'mainCity',''),nullif(r->>'region','')),'Active');
  END IF;
  INSERT INTO ubl_site_orders(site_id,source_row,branch_code,site_name,region,main_city,configuration_id,pricing_stage,po_number,po_issued_date,legacy_ipo_number,status,notes,baseline,source)
  VALUES(linked_site,(r->>'sourceRow')::integer,r->>'branchCode',r->>'name',r->>'region',r->>'mainCity',r->>'configuration',r->>'pricingStage',r->>'poNumber',(r->>'poIssuedDate')::date,r->>'legacyIpoNumber',r->>'status',r->>'notes',nullif(r->'baseline','null'::jsonb),r->'source');
 END LOOP;
END $link$;
